function planCount(p){return (db.plans[p.id]||[]).length}
function plansPage(){return `${pageHeader('CRECÉ A TU PROPIO RITMO','Planes de lectura','Elegí un recorrido, leé cuando tengás tiempo y marcá cada etapa completada. Nada de culpas por perder un día.')}<div class="plan-grid">${PLAN_TEMPLATES.map(p=>`<article class="plan-card"><div class="plan-symbol">${p.symbol}</div><span class="tiny-label">PLAN DE 7 LECTURAS</span><h3>${esc(p.title)}</h3><p>${esc(p.subtitle)}</p><div class="progress-bar"><span style="width:${(planCount(p)/7)*100}%"></span></div><div class="progress-caption">${planCount(p)} de 7 lecturas completadas</div><button class="secondary-btn" data-action="open-plan" data-id="${p.id}">Ver mis lecturas ${ico('arrow')}</button></article>`).join('')}</div><div class="callout"><strong>Tu ritmo importa.</strong> Un plan es una ayuda, no una medida de tu fe. Podés repetirlo todas las veces que querás.</div>`}
function planDetail(id){if($('#app-dialog').open)dialogClose();const p=PLAN_TEMPLATES.find(x=>x.id===id);if(!p)return;const completed=db.plans[p.id]||[];dialogOpen(p.title,`<p class="section-note">${esc(p.subtitle)}</p><div class="progress-bar" style="margin:18px 0"><span style="width:${completed.length/7*100}%"></span></div><div class="plan-checklist">${p.refs.map((r,i)=>`<div class="plan-day"><label><input type="checkbox" data-plan="${p.id}" data-step="${i}" ${completed.includes(i)?'checked':''}/> <span><b>Día ${i+1}</b><small>${esc(r)}</small></span></label><button class="text-link" data-action="plan-read" data-id="${esc(r)}">Leer →</button></div>`).join('')}</div><div class="form-actions"><button class="secondary-btn" data-action="reset-plan" data-id="${p.id}">Reiniciar plan</button><button class="secondary-btn" data-action="close-dialog">Cerrar</button></div>`)}
function calendarPage(){const now=new Date();const month=new Date(now.getFullYear(),now.getMonth()+ui.calendarOffset,1),y=month.getFullYear(),m=month.getMonth();const first=(month.getDay()+6)%7,days=new Date(y,m+1,0).getDate(),title=month.toLocaleDateString('es-CR',{month:'long',year:'numeric'});const cells=Array.from({length:first},()=>'<div></div>').concat(Array.from({length:days},(_,i)=>{const day=i+1,key=`${y}-${pad(m+1)}-${pad(day)}`,n=db.notes.filter(x=>x.date===key).length,p=db.prayers.filter(x=>x.date===key).length,read=(db.reading[key]||[]).length;return `<button class="calendar-day ${key===dateKey()?'current':''} ${n||p||read?'filled':''}" data-action="calendar-day" data-id="${key}"><b>${day}</b><span>${n?'✦':''}${p?'♡':''}${read?'•':''}</span></button>`}));const sessions=Object.values(db.reading).reduce((a,v)=>a+(Array.isArray(v)?v.length:0),0);return `${pageHeader('LAS HUELLAS DE TU CAMINO','Mi calendario espiritual','Recordá cuándo estudiaste, escribiste y descansaste. No se trata de competir, sino de mirar tu recorrido.')}<div class="stats-grid">${stat(db.notes.length,'Reflexiones','journal')}${stat(db.research.length,'Investigaciones','search')}${stat(sessions,'Capítulos marcados','book')}${stat(getStreak(),'Días seguidos','spark')}</div><div class="calendar-panel"><div class="calendar-top"><button class="secondary-btn" data-action="month-prev">‹</button><h2>${esc(title)}</h2><button class="secondary-btn" data-action="month-next">›</button></div><div class="calendar-grid">${['L','M','M','J','V','S','D'].map(day=>`<strong>${day}</strong>`).join('')}${cells.join('')}</div><p class="calendar-legend">✦ Diario &nbsp; ♡ Oraciones &nbsp; • Lecturas registradas</p></div><div class="panel" style="margin-top:22px"><h3>Tu pequeño ritual de hoy</h3><p class="section-note">Marcá lo que te haya ayudado hoy; es completamente opcional.</p>${[['leer','Leer un capítulo'],['orar','Momento de oración'],['anotar','Escribir una reflexión'],['agradecer','Dar gracias']].map(([k,label])=>`<label class="habit-check"><input type="checkbox" data-habit="${k}" ${(db.habits[dateKey()]||[]).includes(k)?'checked':''}/> ${esc(label)}</label>`).join('')}</div>`}
function calendarDetail(day){const notes=db.notes.filter(x=>x.date===day),prayers=db.prayers.filter(x=>x.date===day),reading=db.reading[day]||[];dialogOpen(`Mi día · ${prettyDate(day)}`,`<div class="calendar-day-detail"><h4>Reflexiones</h4>${notes.length?notes.map(n=>`<button class="recent-row" data-action="read-note" data-id="${esc(n.id)}">${esc(n.title)} →</button>`).join(''):'<p>No hay entradas del diario.</p>'}<h4>Oraciones</h4>${prayers.length?prayers.map(x=>`<p>♡ ${esc(x.title)}</p>`).join(''):'<p>No registraste oraciones.</p>'}<h4>Lecturas</h4>${reading.length?reading.map(x=>`<p>✦ ${esc(x)}</p>`).join(''):'<p>Sin lecturas registradas.</p>'}</div><div class="form-actions"><button class="primary-btn" data-action="new-note">Escribir una reflexión</button></div>`)}
function handleEpicAction(button){const a=button.dataset.action||'',target=button.dataset.id||'';switch(a){
case 'bible-prev':turnPage(-1);return true;
case 'bible-next':turnPage(1);return true;
case 'bible-retry':loadScripture();return true;
case 'bible-save-verse':case 'bible-save-compare':bibleNewVerse(target,button.dataset.translation||db.settings.translation);return true;
case 'bible-mark-read':{const k=dateKey(),ref=passageRef(ui.book,ui.chapter),arr=db.reading[k]||[];if(!arr.includes(ref))arr.push(ref);db.reading[k]=arr;save();toast('Lectura registrada para hoy ✦');return true}
case 'new-research':dialogClose();researchForm();return true;
case 'edit-research':dialogClose();researchForm(target);return true;
case 'read-research':researchDetail(target);return true;
case 'delete-research':confirmBox('¿Eliminar investigación?','Esta ficha se borrará. Descargá un respaldo si querés conservarla.','confirm-delete-research',target);return true;
case 'confirm-delete-research':db.research=db.research.filter(r=>r.id!==target);save();dialogClose();render();toast('Investigación eliminada.');return true;
case 'open-plan':planDetail(target);return true;
case 'reset-plan':db.plans[target]=[];save();planDetail(target);toast('Plan reiniciado.');return true;
case 'plan-read':dialogClose();navigate('biblia');jumpToRef(target);return true;
case 'month-prev':ui.calendarOffset--;render();return true;
case 'month-next':ui.calendarOffset++;render();return true;
case 'calendar-day':calendarDetail(target);return true;
default:return false}}
function handleEpicForm(form,kind){if(kind==='jump'){const ref=fieldVal(form,'ref');if(!jumpToRef(ref))toast('No reconocí esa referencia. Probá, por ejemplo: Juan 3:16.');return true}if(kind==='research'){const editId=form.dataset.id||'',r={id:editId||id(),date:fieldVal(form,'date'),topic:fieldVal(form,'topic'),question:fieldVal(form,'question'),texts:fieldVal(form,'texts'),sources:fieldVal(form,'sources'),pro:fieldVal(form,'pro'),against:fieldVal(form,'against'),conclusion:fieldVal(form,'conclusion'),status:fieldVal(form,'status'),volumeId:fieldVal(form,'volumeId')};if(!r.topic){toast('Poné un título para tu investigación.');return true}const pos=db.research.findIndex(x=>x.id===editId);if(pos>=0)db.research[pos]=r;else db.research.push(r);save();dialogClose();render();toast('Investigación guardada ✦');return true}return false}
function handleEpicChange(el){if(el.dataset.plan!==undefined){const key=el.dataset.plan,step=Number(el.dataset.step),arr=db.plans[key]||[];db.plans[key]=el.checked?[...new Set([...arr,step])]:arr.filter(i=>i!==step);save();planDetail(key);return true}if(el.dataset.habit!==undefined){const k=dateKey(),step=el.dataset.habit,arr=db.habits[k]||[];db.habits[k]=el.checked?[...new Set([...arr,step])]:arr.filter(i=>i!==step);save();return true}if(el.id==='epic-book'){ui.book=Number(el.value);ui.chapter=1;render();return true}if(el.id==='epic-chapter'){ui.chapter=Number(el.value);render();return true}if(el.id==='epic-version'){db.settings.translation=el.value;save();render();return true}if(el.id==='epic-version-a'){ui.compareA=el.value;render();return true}if(el.id==='epic-version-b'){ui.compareB=el.value;render();return true}return false}



