function dailyFocus(){const d=parseLocal(dateKey());const i=Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/86400000);const [ref,prompt]=FOCUS_VERSES[((i%FOCUS_VERSES.length)+FOCUS_VERSES.length)%FOCUS_VERSES.length];return {ref,prompt}}
function dailyVerseWidget(){const {ref,prompt}=dailyFocus();const done=!!db.daily?.[dateKey()];return `<section class="daily-feature"><div class="daily-head"><span class="tiny-label">✦ VERSÍCULO DEL DÍA</span><span class="daily-date">${prettyDate(dateKey(),{weekday:'long',day:'numeric',month:'long'})}</span></div><h2>${esc(ref)}</h2><div id="daily-text" class="daily-scripture"><span>Buscando lectura…</span></div><p class="daily-prompt">${esc(prompt)}</p><div class="daily-actions"><button class="primary-btn" data-action="daily-open" type="button">${ico('book')} Leer el pasaje</button><button class="secondary-btn" data-action="daily-reflect" type="button">${ico('edit')} Mi reflexión</button><button class="secondary-btn" data-action="daily-mark" type="button">${ico('check')} ${done?'Leído hoy ✓':'Marcar leído'}</button><a class="secondary-btn" target="_blank" rel="noopener noreferrer" href="https://www.jw.org/es/biblioteca/biblia/">TNM oficial ↗</a></div><div class="daily-foot">Texto diario en Reina-Valera 1909 (cuando hay conexión); la referencia y pregunta siempre están disponibles.</div></section>`}
function todayPage(){return `${pageHeader('UN MOMENTO PARA CADA DÍA','Versículo diario','Un texto distinto cada día, una pregunta abierta y el espacio para escribir tu propia reflexión.')}${dailyVerseWidget()}<div class="callout"><strong>Cómo usarlo:</strong> leé el contexto del capítulo, compará versiones y escribí lo que pensás. Tu ritmo de estudio no es una competencia.</div>`}
let lastDaily=0;
async function loadDailyVerse(){const el=$('#daily-text');if(!el)return;const token=++lastDaily;const {ref}=dailyFocus();const m=ref.match(/^(.*?)\s+(\d+):(\d+)/);if(!m)return;
 const book=BOOKS.findIndex(b=>b[0]===m[1]);if(book===-1)return;
 try{const data=await getChapter('valera',book+1,Number(m[2]));if(token!==lastDaily||!$('#daily-text'))return;
 const v=data.find(x=>x.verse===Number(m[3]));$('#daily-text').textContent=v?.text||'Leé el capítulo completo para conocer el contexto.';
 }catch{if(token===lastDaily&&$('#daily-text'))$('#daily-text').textContent='Texto no disponible sin conexión. Podés abrir la referencia en el lector cuando tengas internet.'}}
