function pdfHref(doc,page=1){return `./estudios/${encodeURIComponent(doc.pdf)}#page=${Math.max(1,page)}`}
function booksPage(){return `${pageHeader('TUS INVESTIGACIONES REUNIDAS','Nuestra biblioteca','¡Tus estudios originales completos, aquí mismo! Libros para leer, buscar, contrastar y seguir investigando.')}
 <div class="library-intro"><span>✦ ${ORIGINAL_BOOKS.reduce((sum,x)=>sum+x.pages,0)} páginas disponibles</span><p>Los libros incluidos son materiales de investigación. Compará siempre las afirmaciones con sus fuentes: no representan conclusiones definitivas ni sustituyen tu propio estudio.</p></div>
 <div class="book-shelf">${ORIGINAL_BOOKS.map(b=>`<article class="original-book"><div class="book-cover"><div class="book-symbol">${b.symbol}</div><div class="book-cover-title">${esc(b.title)}</div><div class="book-cover-sub">${esc(b.subtitle)}</div></div><div class="original-book-info"><span class="tiny-label">${b.pages} PÁGINAS · PDF COMPLETO</span><h3>${esc(b.title)}</h3><p>${esc(b.description)}</p><div class="tag-wrap">${b.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><a class="primary-btn" target="_blank" rel="noopener noreferrer" href="${pdfHref(b)}">${ico('book')} Abrir libro completo ↗</a></div></article>`).join('')}</div>
 <section class="library-search-section"><div class="section-heading"><h2>Buscar dentro de nuestros libros</h2></div><p class="section-note">Buscá una palabra o frase en el texto de los tres libros. Tocá un resultado para abrir la página exacta del PDF.</p><div class="list-search"><span>${ico('search')}</span><input id="book-search" autocomplete="off" value="${esc(libraryQuery)}" placeholder="Ej. Shabat, Mesías, Jesús, Corán, Trinidad…" aria-label="Buscar en los libros" /></div><div id="book-results" aria-live="polite">${libraryQuery?'Buscando…':'<p class="section-note">Escribí arriba para buscar entre las páginas.</p>'}</div></section>
 <section><div class="section-heading"><h2>Guía para retomar nuestros estudios</h2><span class="eyebrow">20 TEMAS PARA INVESTIGAR</span></div><p class="section-note">Estos temas son fichas de navegación preparadas a partir de lo que venimos estudiando. No son transcripciones literales de nuestras conversaciones ni conclusiones tuyas.</p><div class="guide-grid">${STUDY_GUIDES.map((g,i)=>`<article class="guide-card"><span class="tiny-label">${esc(ORIGINAL_BOOKS.find(b=>b.id===g[0])?.title)}</span><h3>${esc(g[1])}</h3><p>${esc(g[2])}</p><div class="verse-reference">${ico('bookmark')} ${esc(g[3])}</div><button class="secondary-btn" data-action="study-topic" data-id="${i}">${ico('edit')} Crear ficha de estudio</button></article>`).join('')}</div></section>`}
async function getBooksIndex(){if(!booksIndexPromise)booksIndexPromise=fetch('./estudios/indice.json').then(r=>{if(!r.ok)throw Error('No está disponible el índice');return r.json()}).catch(e=>{booksIndexPromise=null;throw e});return booksIndexPromise}
async function searchLibrary(term){libraryQuery=String(term||'').slice(0,100);const root=$('#book-results');if(!root)return;if(libraryQuery.trim().length<2){root.innerHTML='<p class="section-note">Escribí al menos 2 caracteres para buscar.</p>';return}root.textContent='Buscando en los libros…';const query=libraryQuery.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();try{const idx=await getBooksIndex();if(libraryQuery.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase()!==query)return;let hits=0,results=[];
 for(const [key,pages] of Object.entries(idx)){const doc=ORIGINAL_BOOKS.find(b=>b.id===key);if(!doc)continue;for(const p of pages){const content=String(p.t||''),norm=content.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();const at=norm.indexOf(query);if(at>=0){hits++;if(results.length<24){const begin=Math.max(0,at-100),end=Math.min(content.length,at+query.length+180);const snippet=content.slice(begin,end).replace(/\s+/g,' ');results.push(`<a class="book-hit" href="${pdfHref(doc,p.p)}" target="_blank" rel="noopener noreferrer"><span class="tiny-label">${esc(doc.title)} · PÁGINA ${p.p}</span><p>…${esc(snippet)}…</p><span class="text-link">Abrir página ↗</span></a>`)}}}}
 root.innerHTML=`<p class="section-note">${hits} páginas con coincidencias${hits>24?' · se muestran las primeras 24':''}.</p>${results.length?'<div class="book-hits">'+results.join('')+'</div>':'<p>No se encontraron coincidencias. Probá otra palabra o frase.</p>'}`;
 }catch{root.innerHTML='<p class="setting-notice">No se pudo cargar el índice. Revisá la conexión o recargá el sitio.</p>'}}
function tnmPanel(){const key=`${ui.book}:${ui.chapter}`,value=db.tnmNotes?.[key]||'';return `<section class="tnm-panel"><div class="eyebrow">✦ TRADUCCIÓN DEL NUEVO MUNDO</div><h2>${esc(passageRef(ui.book,ui.chapter))}</h2><p>Podés leer esta edición directamente en la biblioteca oficial de jw.org. El texto completo no se incluye en la aplicación porque está protegido por derechos de autor.</p><a class="primary-btn" href="https://www.jw.org/es/biblioteca/biblia/" target="_blank" rel="noopener noreferrer">${ico('book')} Abrir TNM en jw.org ↗</a><div class="field" style="margin-top:19px"><label for="tnm-notes">Mis notas personales sobre ${esc(passageRef(ui.book,ui.chapter))}</label><textarea id="tnm-notes" rows="5" maxlength="6000" placeholder="Anotá el número de versículo, las diferencias que observaste, el contexto o tus preguntas…">${esc(value)}</textarea></div><div class="setting-actions"><button class="secondary-btn" type="button" data-action="tnm-save">${ico('check')} Guardar mis notas</button><button class="secondary-btn" type="button" data-action="tnm-research">${ico('search')} Comparar doctrinas</button></div><p class="source-note">Tus anotaciones son privadas del navegador que utilizás. Al comparar con otras ediciones, consultá también sus contextos y notas editoriales.</p></section>`}
function handleFinalAction(button){const act=button.dataset.action||'';if(act==='daily-open'||act==='daily-reflect'){
 const ref=dailyFocus().ref;if(act==='daily-reflect'){noteForm('',{type:'Reflexión'});const t=$('#app-dialog [name="references"]');if(t)t.value=ref;const title=$('#app-dialog [name="title"]');if(title)title.value='Reflexión de hoy · '+ref;
 }else{navigate('biblia');jumpToRef(ref)}return true}
 if(act==='daily-mark'){db.daily=db.daily||{};db.daily[dateKey()]=!db.daily[dateKey()];save();render();toast(db.daily[dateKey()]?'Lectura de hoy registrada ✦':'Marca de lectura eliminada');return true}
 if(act==='tnm-save'){const k=`${ui.book}:${ui.chapter}`;db.tnmNotes=db.tnmNotes||{};db.tnmNotes[k]=String($('#tnm-notes')?.value||'').slice(0,6000);save();toast('Tus notas sobre la TNM se guardaron ✦');return true}
 if(act==='tnm-research'){researchForm();const e=$('#app-dialog [name="topic"]');if(e)e.value='Comparación de traducciones · '+passageRef(ui.book,ui.chapter);const tx=$('#app-dialog [name="texts"]');if(tx)tx.value=passageRef(ui.book,ui.chapter);return true}
 if(act==='study-topic'){const g=STUDY_GUIDES[Number(button.dataset.id)];if(!g)return true;researchForm();const a=$('#app-dialog [name="topic"]'),b=$('#app-dialog [name="question"]'),c=$('#app-dialog [name="texts"]'),d=$('#app-dialog [name="sources"]');if(a)a.value=g[1];if(b)b.value=g[2];if(c)c.value=g[3];if(d)d.value=ORIGINAL_BOOKS.find(x=>x.id===g[0])?.title+' (PDF completo, disponible en Nuestros libros)';return true}
 return false}
function handleFinalChange(){return false}

handlers();render();
